#[test]
fn revl_lifecycle_crasher_lifecycle_boots_and_unloads_clean() {
    // drives the composition on a real cordis-rs context and
    // proves no residue after LIFO teardown (FR-5 / §7.1).
    let root = cordis::Context::new();
    let mut _revl_fibers: Vec<(&str, cordis::Fiber)> = Vec::new();
    {
        let _cfg = serde_json::json!({"Crasher": {}});
        let _f = _revl_load(&root, "crasher", &_cfg).expect("lifecycle test \"crasher lifecycle boots and unloads clean\": load Crasher");
        _f.wait().expect("lifecycle test \"crasher lifecycle boots and unloads clean\": Crasher did not reach ACTIVE (R2)");
        _revl_fibers.push(("crasher", _f));
    }
    if let Some(pos) = _revl_fibers.iter().position(|(n, _)| *n == "crasher") {
        let (_, _f) = _revl_fibers.remove(pos);
        _f.dispose().expect("lifecycle test \"crasher lifecycle boots and unloads clean\": unload Crasher");
    }
    // R4 + R1: the composition must leave the live runtime
    // holding nothing — no plugin, no provided service, no
    // unreleased host resource — the same checks the py
    // reference tier's `assert no_residue` performs and the
    // registry/reflect half of `revl run --once`.
    assert!(root.registry().len() == 0 && root.reflect().services().len() == 0 && REVL_LIVE_HOST_RESOURCES.with(|c| c.get()) == 0,
            "lifecycle test \"crasher lifecycle boots and unloads clean\": residue — the host runtime still holds state (R4/R1)");
}

